def test_coletar_dados_aceita_tudo_de_primeira(capsys):
    dados = coletar_dados(
        _Transcricao(), "conv-teste", entrada=_respostas("30", "2020", "[REDIGIDO]", "completo", "2026-10-01")
    )

    assert dados == {
        "idade": 30,
        "veiculo_ano": 2020,
        "cep": "[REDIGIDO]",
        "plano_id": "completo",
        "data_inicio": "2026-10-01",
    }
    capsys.readouterr()  # silencia a saída da coleta neste teste


def test_coletar_dados_campos_opcionais_em_branco():
    dados = coletar_dados(_Transcricao(), "conv-teste", entrada=_respostas("30", "2020", "[REDIGIDO]", "", ""))

    assert dados["plano_id"] is None
    assert dados["data_inicio"] is None


def test_coletar_dados_reprompta_cep_invalido(capsys):
    dados = coletar_dados(
        _Transcricao(), "conv-teste", entrada=_respostas("30", "2020", "abc", "[REDIGIDO]", "", "")
    )

    assert dados["cep"] == "[REDIGIDO]"
    assert "inválido" in capsys.readouterr().out


def test_coletar_dados_reprompta_campo_obrigatorio_em_branco(capsys):
    dados = coletar_dados(
        _Transcricao(), "conv-teste", entrada=_respostas("", "30", "2020", "[REDIGIDO]", "", "")
    )

    assert dados["idade"] == 30
    assert "obrigatório" in capsys.readouterr().out

